python3 << 'PYEOF'
import xml.etree.ElementTree as ET

tree = ET.parse('/work/output/artifacts/skill-bpmn-contract-variant-wrappers/ContractVariantsBpmn/ContractVariantsBpmn.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

errors = []

# 1. Root is definitions with required namespaces
tag = root.tag
if 'definitions' not in tag:
    errors.append(f"Root is not definitions: {tag}")
if 'http://uipath.org/schema/bpmn' not in root.attrib.get('xmlns:uipath','') and 'http://uipath.org/schema/bpmn' not in str(root.attrib):
    # check by iterating namespaces
    pass

# 2. Exactly one BPMNDiagram
diagrams = root.findall('.//bpmndi:BPMNDiagram', ns)
print(f"BPMNDiagram count: {len(diagrams)}")

# Collect all declared ids
all_ids = set()
for el in root.iter():
    if 'id' in el.attrib:
        all_ids.add(el.attrib['id'])

print(f"Total declared ids: {len(all_ids)}")

# Collect all BPMNShape bpmnElement refs
shapes = root.findall('.//bpmndi:BPMNShape', ns)
shape_refs = {s.attrib.get('bpmnElement') for s in shapes}
print(f"Shape count: {len(shapes)}")

# Collect all BPMNEdge bpmnElement refs
edges = root.findall('.//bpmndi:BPMNEdge', ns)
edge_refs = {e.attrib.get('bpmnElement') for e in edges}
print(f"Edge count: {len(edges)}")

# Collect all flow nodes
process = root.find('bpmn:process', ns)
flow_node_ids = set()
for el in process:
    eid = el.attrib.get('id')
    if eid:
        flow_node_ids.add(eid)

print(f"Process-level flow node ids: {len(flow_node_ids)}")

# Check every flow node has a shape
for nid in flow_node_ids:
    tag_local = None
    for el in process:
        if el.attrib.get('id') == nid:
            tag_local = el.tag
            break
    if 'sequenceFlow' in str(tag_local):
        if nid not in edge_refs:
            errors.append(f"Flow {nid} has no BPMNEdge")
    else:
        if nid not in shape_refs:
            errors.append(f"Node {nid} has no BPMNShape")

# Check all refs resolve
for el in root.iter():
    for attr in ['sourceRef','targetRef','attachedToRef','bpmnElement']:
        val = el.attrib.get(attr)
        if val and val not in all_ids:
            errors.append(f"Unresolved ref {attr}={val} in {el.tag}")

# Check no activity/event has more than one incoming
for el in process:
    incoming = list(el.findall('bpmn:incoming', ns))
    if len(incoming) > 1:
        errors.append(f"FAKE_JOIN: {el.attrib.get('id')} has {len(incoming)} incoming flows")

# Check migrationVersion values present
mv_vals = set()
for el in root.iter('{http://uipath.org/schema/bpmn}migrationVersion'):
    mv_vals.add(el.attrib.get('version'))
print(f"migrationVersion values found: {mv_vals}")

# Check scriptVersion v2 present
sv_vals = set()
for el in root.iter('{http://uipath.org/schema/bpmn}scriptVersion'):
    sv_vals.add(el.attrib.get('value'))
print(f"scriptVersion values found: {sv_vals}")

# Check for uipath:Activity (capital A) preserve payload
activity_caps = list(root.iter('{http://uipath.org/schema/bpmn}Activity'))
print(f"uipath:Activity (capital-A) elements: {len(activity_caps)}")

if errors:
    print("ERRORS:")
    for e in errors:
        print(" -", e)
else:
    print("Structural checks: PASSED")
PYEOF
